function save(p) {
  const file = files.get(p.pid);
  if (!file) {
    if (p.owner === id) return toast('Yours');
    if (incoming.has(p.pid)) return toast('Receiving…');   // already asked: don't ask twice
    if (onMyScreen(p)) return dropped(p);                  // on my screen: a tap fetches it, like a drop (C6)
    return toast('Drag it onto your screen first');
  }
  if (p.owner === id) return toast('Already yours');
  // handed over once it was shared or its download started, so Save all doesn't save it again (F13)
  if (navigator.canShare?.({ files: [file] })) navigator.share({ files: [file] }).then(() => saveAll.handed.add(p.pid), () => {});
  else { downloadFile(file); saveAll.handed.add(p.pid); }

async function tap() {
  if (busy) return toast('Still saving');
  const { ready, arriving } = batch(handed);
  if (!ready.length) return toast(arriving ? `Nothing to save yet${more(arriving)}` : 'Nothing new to save');
  const list = ready.map((r) => r.file);
  let sharing = false;
  if (!downloadNext) { try { sharing = !!canShare(list); } catch { sharing = false; } }
  busy = true;

  toast(`Downloading ${ready.length}${more(arriving)}`);
  for (let i = 0; i < ready.length; i++) {
    if (i) await wait(DOWNLOAD_GAP);
    try { download(ready[i].file); handed.add(ready[i].pid); } catch (e) { console.warn('download failed', ready[i].file?.name, e); }
  }
} finally { busy = false; }

